local M = {}

---@param opts table?
M.setup = function (opts)

end

---Mostly for internal use but maybe you can get some use out of it.
---@param query string: The query to run, for a full list of currently implemented syntax, please see #FILE#.
---@return table?: The results of the query.
---@param allCards boolean?: If true will use all loaded cards, rather than the table of cards generated by the default query.
M.query = function (query, allCards)
  if M.oracleObjects == nil then
    return nil
  elseif query == "" or query == nil then
    return M.oracleObjects
  end

  local parsedQuery = M.queryParser:match(query)
  local results = {}

  for _, oracleObject in pairs(M.oracleObjects) do
    local addObject = false

    for _, qObject in pairs(parsedQuery) do
      if type(qObject) == 'string' then
        if not oracleObject.name:lower():find(qObject:lower(), 1, true) then
          addObject = false
          break
        end

      elseif type(qObject) == "table" then
        if not qObject:compare(oracleObject) then
          addObject = false
          break
        end
      end

      addObject = true
    end

    if addObject then
      table.insert(results, oracleObject)
    end
  end

  return results
end

---Open the picker window.
---@param prequery string?: Use this to further narrow down cards. Ideal for narrowing by format, color identity for commander, available game types.
---@param allCards boolean?: If true will use all loaded cards, rather than the table of cards generated by the default query. Will still run the prequery, if given.
M.picker = function (prequery, allCards)

end

---Set the query used to filter out entirely unwanted cards, such as art carts and tokens.
---Sets the primary table to the result of the given query.
---@param query string: The query to run.
M.setDefaultQuery = function (query)

end

M.updateCards = function ()
  local tempFileName = os.tmpname()

  local ok, str, code = os.execute("curl https://api.scryfall.com/bulk-data/oracle-cards" .. curlArgs ..  "> " .. tempFileName)

  if not ok then
    print(str .. code)
    return
  end

  local tempFile = io.open(tempFileName)
  if tempFile == nil then
    return
  end
  local json = tempFile:read()

  local jsonObj = vim.json.decode(json, {object = true, array = true})
  os.execute("curl " .. jsonObj.download_uri .. curlArgs .. "-o " .. M.bulkDataPath)
end

M.loadCards = function ()
  local bulkDataJson = io.input(M.bulkDataPath):read("a")
  M.oracleObjects = vim.json.decode(bulkDataJson, {object = true, array = true})
end

return M
